import { ApiRequestError, type FuulApiClient } from '../http/fuul-api-client.js';
import type { CheckEventStatusInput, SendBatchEventsInput, SendEventInput, SendEventPayload } from '../tools/tool-schemas.js';

export function buildSendEventBody(fields: SendEventPayload): Record<string, unknown> {
  const body: Record<string, unknown> = {
    name: fields.name,
    dedup_id: fields.dedup_id,
    user: {
      identifier: fields.user_identifier,
      identifier_type: fields.user_identifier_type,
    },
  };
  if (fields.args != null) {
    body.args = fields.args;
  }
  if (fields.timestamp != null) {
    body.timestamp = fields.timestamp;
  }
  return body;
}

export async function runSendEvent(api: FuulApiClient, bearer: string, input: SendEventInput): Promise<unknown> {
  assertWriteConfirmedOrDryRun(input);
  const body = buildSendEventBody(input);
  const path = '/api/v1/events';

  if (input.dry_run === true) {
    return { dry_run: true, would_post: path, body };
  }

  const data = await api.postJson(path, body, { bearerToken: bearer });
  return data ?? { status: 'created' };
}

export async function runSendBatchEvents(api: FuulApiClient, bearer: string, input: SendBatchEventsInput): Promise<unknown> {
  assertWriteConfirmedOrDryRun(input);
  const body = input.events.map((e) => buildSendEventBody(e));
  const path = '/api/v1/events/batch';

  if (input.dry_run === true) {
    return { dry_run: true, would_post: path, event_count: body.length, body };
  }

  return api.postJson(path, body, { bearerToken: bearer });
}

function buildEventPipelineQuery(input: CheckEventStatusInput): Record<string, string> {
  const query: Record<string, string> = {};
  if (input.event_id) {
    query.event_id = input.event_id;
  }
  if (input.dedup_id) {
    query.dedup_id = input.dedup_id;
  }
  if (input.event_name) {
    query.event_name = input.event_name;
  }
  return query;
}

export async function runCheckEventStatus(api: FuulApiClient, bearer: string, input: CheckEventStatusInput): Promise<unknown> {
  if (input.verbose === true) {
    try {
      return await api.getJson('/api/v1/events/pipeline', {
        bearerToken: bearer,
        query: buildEventPipelineQuery(input),
      });
    } catch (error: unknown) {
      if (error instanceof ApiRequestError && error.status === 404) {
        return { created: false };
      }
      throw error;
    }
  }

  return api.getJson('/api/v1/events/status', {
    bearerToken: bearer,
    query: {
      user_identifier: input.user_identifier!,
      user_identifier_type: input.user_identifier_type!,
      event_name: input.event_name!,
    },
  });
}

import type { AxiosResponse } from 'axios';
import { describe, expect, it } from 'vitest';

import { ApiRequestError, throwIfNotSuccess } from './fuul-api-client.js';

function mockRes(status: number, data: unknown, headers: Record<string, string> = {}): AxiosResponse {
  return {
    status,
    data,
    statusText: '',
    headers,
    config: {} as never,
  };
}

describe('throwIfNotSuccess', () => {
  it('passes for 200', () => {
    expect(() => throwIfNotSuccess(mockRes(200, {}))).not.toThrow();
  });

  it('throws ApiRequestError for 400 with message', () => {
    expect(() => throwIfNotSuccess(mockRes(400, { message: 'bad' }))).toThrow(ApiRequestError);
    try {
      throwIfNotSuccess(mockRes(400, { message: 'bad' }));
    } catch (e) {
      expect(e instanceof ApiRequestError && e.message).toBe('bad');
    }
  });

  it('throws ApiRequestError for 429', () => {
    expect(() => throwIfNotSuccess(mockRes(429, {}, { 'retry-after': '10' }))).toThrow(ApiRequestError);
    try {
      throwIfNotSuccess(mockRes(429, {}, { 'retry-after': '10' }));
    } catch (e) {
      expect(e instanceof ApiRequestError && e.status).toBe(429);
      expect(e instanceof ApiRequestError && e.retryAfterSeconds).toBe(10);
    }
  });
});

import axios, { type AxiosInstance, type AxiosResponse } from 'axios';

import { OAuthClient } from '../auth/oauth-client.js';
import { TokenStore } from '../auth/token-store.js';
import { apiOriginFromEnv, type Env } from '../config/env.js';
import { formatRateLimitMessage, parseRetryAfterFromHeaders } from './retry-after.js';

const REQUEST_TIMEOUT_MS = 30_000;

export class NotLoggedInError extends Error {
  readonly code = 'NOT_LOGGED_IN' as const;

  constructor() {
    super('Not logged in. Run: fuul-mcp login');
    this.name = 'NotLoggedInError';
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

export class ApiRequestError extends Error {
  readonly code = 'API_REQUEST_ERROR' as const;

  constructor(
    message: string,
    readonly status: number,
    readonly body?: unknown,
    /** Seconds until retry when HTTP 429 and Retry-After is present. */
    readonly retryAfterSeconds?: number,
  ) {
    super(message);
    this.name = 'ApiRequestError';
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

type AuthorizedRequestOptions = {
  method: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';
  url: string;
  headers?: Record<string, string>;
  /** Query string params (GET, etc.). */
  params?: Record<string, unknown>;
  data?: unknown;
  /**
   * When set, sends this Bearer and skips OAuth token store (no refresh on 401).
   * Used for project API key routes such as /api/v1/project-affiliates.
   */
  bearerToken?: string;
};

/**
 * Authenticated Fuul API client: Bearer from ~/.fuul/tokens.json, refresh + one retry on 401.
 */
export class FuulApiClient {
  private readonly http: AxiosInstance;

  constructor(
    env: Env,
    private readonly tokenStore: TokenStore,
    private readonly oauth: OAuthClient,
  ) {
    this.http = axios.create({
      baseURL: apiOriginFromEnv(env),
      timeout: REQUEST_TIMEOUT_MS,
      headers: { 'Content-Type': 'application/json' },
      validateStatus: () => true,
    });
  }

  /** GET /api/v1/auth/user — same contract as `fuul-mcp whoami`. */
  async getAuthUser(): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'GET',
      url: '/api/v1/auth/user',
    });
    if (res.status !== 200) {
      throw apiErrorFromResponse(res);
    }
    return res.data;
  }

  /**
   * Authenticated GET (Bearer + refresh on 401). Exposes status and headers for cacheable endpoints (e.g. metadata).
   */
  async getAuthorized(
    url: string,
    extraHeaders?: Record<string, string>,
    query?: Record<string, unknown>,
  ): Promise<{
    status: number;
    data: unknown;
    etag: string | undefined;
    cacheControl: string | undefined;
    retryAfterSeconds: number | undefined;
  }> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'GET',
      url,
      headers: extraHeaders,
      params: query,
    });
    return {
      status: res.status,
      data: res.data,
      etag: readHeader(res, 'etag'),
      cacheControl: readHeader(res, 'cache-control'),
      retryAfterSeconds: parseRetryAfterFromHeaders(res.headers),
    };
  }

  async getJson(
    url: string,
    options?: { query?: Record<string, unknown>; headers?: Record<string, string>; bearerToken?: string },
  ): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'GET',
      url,
      headers: options?.headers,
      params: options?.query,
      bearerToken: options?.bearerToken,
    });
    throwIfNotSuccess(res);
    return res.data;
  }

  async postJson(url: string, body: unknown, options?: { bearerToken?: string }): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'POST',
      url,
      data: body,
      bearerToken: options?.bearerToken,
    });
    throwIfNotSuccess(res);
    return res.data;
  }

  async patchJson(url: string, body: unknown, options?: { bearerToken?: string }): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'PATCH',
      url,
      data: body,
      bearerToken: options?.bearerToken,
    });
    throwIfNotSuccess(res);
    return res.data;
  }

  async putJson(url: string, body: unknown, options?: { bearerToken?: string }): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'PUT',
      url,
      data: body,
      bearerToken: options?.bearerToken,
    });
    throwIfNotSuccess(res);
    return res.data;
  }

  async deleteJson(url: string, options?: { bearerToken?: string; query?: Record<string, unknown>; data?: unknown }): Promise<unknown> {
    const res = await this.executeAuthorizedRequest<unknown>({
      method: 'DELETE',
      url,
      params: options?.query,
      data: options?.data ?? {},
      bearerToken: options?.bearerToken,
    });
    throwIfNotSuccess(res);
    if (res.status === 204 || res.data == null || res.data === '') {
      return { status: 'deleted' };
    }
    return res.data;
  }

  private async executeAuthorizedRequest<T>(opts: AuthorizedRequestOptions): Promise<AxiosResponse<T>> {
    if (opts.bearerToken) {
      return this.http.request<T>({
        method: opts.method,
        url: opts.url,
        headers: {
          Authorization: `Bearer ${opts.bearerToken}`,
          'Content-Type': 'application/json',
          ...opts.headers,
        },
        params: opts.params,
        data: opts.data,
      });
    }

    let tokens = await this.tokenStore.read();
    if (!tokens?.access_token) {
      throw new NotLoggedInError();
    }

    const run = (accessToken: string) =>
      this.http.request<T>({
        method: opts.method,
        url: opts.url,
        headers: { Authorization: `Bearer ${accessToken}`, ...opts.headers },
        params: opts.params,
        data: opts.data,
      });

    let res = await run(tokens.access_token);

    if (res.status === 401 && tokens.refresh_token) {
      const refreshed = await this.oauth.refreshFromStore();
      if (refreshed) {
        tokens = refreshed;
        res = await run(tokens.access_token);
      }
    }

    return res;
  }
}

export function throwIfNotSuccess(res: AxiosResponse): void {
  if (res.status >= 200 && res.status < 300) {
    return;
  }
  throw apiErrorFromResponse(res);
}

function apiErrorFromResponse(res: AxiosResponse): ApiRequestError {
  if (res.status === 429) {
    const retryAfter = parseRetryAfterFromHeaders(res.headers);
    return new ApiRequestError(formatRateLimitMessage(retryAfter), 429, res.data, retryAfter);
  }
  return new ApiRequestError(messageFromBody(res.data, res.status), res.status, res.data);
}

function messageFromBody(data: unknown, status: number): string {
  if (data && typeof data === 'object') {
    const o = data as Record<string, unknown>;
    if (typeof o.message === 'string') {
      return o.message;
    }
    if (Array.isArray(o.message)) {
      return o.message.map(String).join('; ');
    }
  }
  return `Request failed (HTTP ${status})`;
}

function readHeader(res: AxiosResponse, name: string): string | undefined {
  const raw = res.headers[name] ?? res.headers[name.toLowerCase()];
  if (raw == null) {
    return undefined;
  }
  return Array.isArray(raw) ? String(raw[0]) : String(raw);
}

import { describe, expect, it } from 'vitest';

import { buildNestQueryString } from './nest-query.js';

describe('buildNestQueryString', () => {
  it('serializes repeated keys for arrays', () => {
    const s = buildNestQueryString({ statuses: ['Active', 'Paused'], foo: 'bar' });
    expect(s).toContain('statuses=Active');
    expect(s).toContain('statuses=Paused');
    expect(s).toContain('foo=bar');
  });

  it('omits empty values', () => {
    expect(buildNestQueryString({ a: '', b: undefined, c: null as unknown as string })).toBe('');
  });

  it('encodes special characters', () => {
    const s = buildNestQueryString({ user_identifier: 'evm:0xabc,test' });
    expect(s).toContain('user_identifier=');
  });
});

/**
 * Serialize query params for NestJS controllers that expect repeated keys
 * (e.g. statuses=Active&statuses=Paused) instead of axios default bracket indexing.
 */
export function buildNestQueryString(params: Record<string, unknown>): string {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null || value === '') {
      continue;
    }
    if (Array.isArray(value)) {
      for (const item of value) {
        if (item !== undefined && item !== null && item !== '') {
          search.append(key, String(item));
        }
      }
    } else {
      search.append(key, String(value));
    }
  }
  return search.toString();
}

