import { extractPublishedTriggersFromCustomizations, mergeTriggersByRef, scopeNestedTrigger } from './merge-triggers-by-ref.js';
import { METADATA_VERSIONS_NOTE, type ScopedIncentive, type ScopedTrigger } from './types.js';

function asRecord(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }
  return value as Record<string, unknown>;
}

export function enrichIncentiveWithTriggerScope(incentive: Record<string, unknown>, mergedByRef: Map<string, ScopedTrigger>): ScopedIncentive {
  const nested = incentive.triggers;
  const triggers: ScopedTrigger[] = [];
  if (Array.isArray(nested)) {
    for (const item of nested) {
      const row = asRecord(item);
      if (row) {
        triggers.push(scopeNestedTrigger(row, mergedByRef));
      }
    }
  }

  return {
    slug: typeof incentive.slug === 'string' ? incentive.slug : '',
    draft_conversion_id: incentive.id != null ? String(incentive.id) : null,
    published_conversion_id: null,
    draft: incentive,
    published: null,
    triggers,
  };
}

export function enrichProjectWithMetadataScope(draftProject: Record<string, unknown>, customizations: unknown): Record<string, unknown> {
  const draftTriggers = draftProject.triggers;
  const merged = mergeTriggersByRef(Array.isArray(draftTriggers) ? draftTriggers : [], extractPublishedTriggersFromCustomizations(customizations));
  const mergedByRef = new Map(merged.map((row) => [row.ref, row]));

  const draftConversions = draftProject.conversions;
  const conversions = Array.isArray(draftConversions)
    ? draftConversions.map((item) => {
        const conversion = asRecord(item);
        return conversion ? enrichIncentiveWithTriggerScope(conversion, mergedByRef) : item;
      })
    : draftConversions;

  return {
    ...draftProject,
    triggers: merged,
    conversions,
    metadata_versions: {
      published_metadata_id: null,
      note: METADATA_VERSIONS_NOTE,
    },
  };
}

export function enrichIncentivesListWithTriggerScope(
  incentives: unknown[],
  customizations: unknown,
  projectDraftTriggers: unknown[] = [],
): ScopedIncentive[] {
  const published = extractPublishedTriggersFromCustomizations(customizations);
  const merged = mergeTriggersByRef(
    projectDraftTriggers.length > 0 ? projectDraftTriggers : collectDraftTriggersFromIncentives(incentives),
    published,
  );
  const mergedByRef = new Map(merged.map((row) => [row.ref, row]));

  return incentives
    .map((item) => asRecord(item))
    .filter((item): item is Record<string, unknown> => item != null)
    .map((incentive) => enrichIncentiveWithTriggerScope(incentive, mergedByRef));
}

export function enrichSingleIncentiveWithTriggerScope(
  incentive: Record<string, unknown>,
  customizations: unknown,
  projectDraftTriggers: unknown[] = [],
): ScopedIncentive {
  const nested = Array.isArray(incentive.triggers) ? incentive.triggers : [];
  const draftTriggers = projectDraftTriggers.length > 0 ? projectDraftTriggers : nested;
  const published = extractPublishedTriggersFromCustomizations(customizations);
  const merged = mergeTriggersByRef(Array.isArray(draftTriggers) ? draftTriggers : [], published);
  const mergedByRef = new Map(merged.map((row) => [row.ref, row]));
  return enrichIncentiveWithTriggerScope(incentive, mergedByRef);
}

function collectDraftTriggersFromIncentives(incentives: unknown[]): unknown[] {
  const out: unknown[] = [];
  for (const item of incentives) {
    const incentive = asRecord(item);
    if (!incentive || !Array.isArray(incentive.triggers)) {
      continue;
    }
    out.push(...incentive.triggers);
  }
  return out;
}

import type { FuulApiClient } from '../http/fuul-api-client.js';
import { withTimeout } from '../util/with-timeout.js';
import { enrichIncentivesListWithTriggerScope, enrichProjectWithMetadataScope, enrichSingleIncentiveWithTriggerScope } from './enrich-responses.js';

const PROJECT_SCOPE_CACHE_TTL_MS = 30_000;

type ProjectScopeCacheEntry = {
  expiresAt: number;
  value: Promise<Record<string, unknown>>;
};

const projectScopeCache = new Map<string, ProjectScopeCacheEntry>();

export function clearProjectScopeCacheForTests(): void {
  projectScopeCache.clear();
}

function asRecord(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {};
  }
  return value as Record<string, unknown>;
}

async function fetchCustomizations(api: FuulApiClient, projectId: string, toolTimeoutMs: number, label: string): Promise<unknown> {
  return withTimeout(api.getJson(`/api/v1/projects/${projectId}/customizations`), toolTimeoutMs, label);
}

export async function loadProjectWithMetadataScope(api: FuulApiClient, projectId: string, toolTimeoutMs: number): Promise<Record<string, unknown>> {
  const now = Date.now();
  const cached = projectScopeCache.get(projectId);
  if (cached && cached.expiresAt > now) {
    return cached.value;
  }

  const value = (async () => {
    const [draftProject, customizations] = await Promise.all([
      withTimeout(api.getJson(`/api/v1/projects/${projectId}`), toolTimeoutMs, 'get_project'),
      fetchCustomizations(api, projectId, toolTimeoutMs, 'get_project_customizations'),
    ]);
    return enrichProjectWithMetadataScope(asRecord(draftProject), customizations);
  })();

  projectScopeCache.set(projectId, { expiresAt: now + PROJECT_SCOPE_CACHE_TTL_MS, value });

  return value;
}

export async function loadIncentivesListWithMetadataScope(api: FuulApiClient, projectId: string, toolTimeoutMs: number): Promise<unknown> {
  const [incentives, customizations, draftProject] = await Promise.all([
    withTimeout(api.getJson(`/api/v1/projects/${projectId}/incentives`), toolTimeoutMs, 'list_incentives'),
    fetchCustomizations(api, projectId, toolTimeoutMs, 'list_incentives_customizations'),
    withTimeout(api.getJson(`/api/v1/projects/${projectId}`), toolTimeoutMs, 'list_incentives_project'),
  ]);

  const project = asRecord(draftProject);
  const projectTriggers = Array.isArray(project.triggers) ? project.triggers : [];
  const list = Array.isArray(incentives) ? incentives : [];

  return enrichIncentivesListWithTriggerScope(list, customizations, projectTriggers);
}

export async function loadIncentiveWithMetadataScope(
  api: FuulApiClient,
  projectId: string,
  conversionId: string,
  toolTimeoutMs: number,
): Promise<unknown> {
  const [incentive, customizations, draftProject] = await Promise.all([
    withTimeout(api.getJson(`/api/v1/projects/${projectId}/incentives/${conversionId}`), toolTimeoutMs, 'get_incentive'),
    fetchCustomizations(api, projectId, toolTimeoutMs, 'get_incentive_customizations'),
    withTimeout(api.getJson(`/api/v1/projects/${projectId}`), toolTimeoutMs, 'get_incentive_project'),
  ]);

  const project = asRecord(draftProject);
  const projectTriggers = Array.isArray(project.triggers) ? project.triggers : [];

  return enrichSingleIncentiveWithTriggerScope(asRecord(incentive), customizations, projectTriggers);
}

